D, X, Y = 2, 4, 3          # facing south, 4 right and 3 down from charger
moves = []
def FW(): moves.append("FW")
def TL(): moves.append("TL")
def turnZero():
    for i in range(D):      # each TL turns 90 deg anti-clockwise
        TL()
def goZero():               # assumes facing north (D = 0)
    for i in range(Y):
        FW()
    TL()                    # now facing west
    for j in range(X):
        FW()
def goBack():
    turnZero()
    goZero()
goBack()
print(" ".join(moves))

seat = [[0]*8 for i in range(5)]   # rows A-E, seats 1-8
row = []; col = []; name = []
def sell(r, c, who):
    seat[r-1][c-1] = "ABCDE"[r-1] + str(c)
    row.append(r); col.append(c); name.append(who)
def sold():
    total = 0
    for i in range(5):
        for j in range(8):
            if seat[i][j] != 0:
                total = total + 1
    return total
def check(r, c):
    customer = "None"
    for i in range(sold()):
        if row[i] == r and col[i] == c:
            customer = name[i]
    return customer
