winner = [158, 161, 168, 170, 173, 178]
def fromMin(num):
    i, steps = 0, 0
    while i <= 5 and num >= winner[i]:
        steps += 1
        if num == winner[i]:
            return True, steps
        i += 1
    return False, steps
def fromMax(num):
    i, steps = 5, 0
    while i >= 0 and num <= winner[i]:
        steps += 1
        if num == winner[i]:
            return True, steps
        i -= 1
    return False, steps
def search(t):
    return fromMin(t) if t <= winner[2] else fromMax(t)
for t in [161, 173, 165]:
    print(t, search(t))

box = ["KLN", "NT", "KLN", "NT", "KLN", "NT", "HK", "HK"]  # index 0 = bottom
def isEmpty(S): return len(S) == 0
def push(S, x): S.append(x)
def pop(S): return S.pop()
def export(L):
    out = []
    while not isEmpty(box):
        temp = pop(box)
        if temp != L:
            push(out, temp)
    while not isEmpty(out):
        push(box, pop(out))
export("NT")
print(box)

